from collections import deque

def transform_rule(s):
 g=[list(map(int,line)) for line in s.splitlines()]; R=len(g); C=len(g[0]);
 # C connected component 4-neighbor 8 from 6
 seeds=[(r,c) for r in range(R) for c in range(C) if g[r][c]==6]
 q=deque()
 for r,c in seeds:
  for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
   rr,cc=r+dr,c+dc
   if 0<=rr<R and 0<=cc<C and g[rr][cc]==8:q.append((rr,cc))
 comp=set()
 while q:
  p=q.popleft()
  if p in comp:continue
  r,c=p
  if g[r][c]!=8:continue
  comp.add(p)
  for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
   rr,cc=r+dr,c+dc
   if 0<=rr<R and 0<=cc<C and g[rr][cc]==8 and (rr,cc) not in comp:q.append((rr,cc))
 # exterior 1s connected to border through 4-connected 1s
 q=deque((r,c) for r in range(R) for c in range(C) if g[r][c]==1 and (r==0 or c==0 or r==R-1 or c==C-1))
 ext1=set()
 while q:
  p=q.popleft()
  if p in ext1:continue
  r,c=p
  if g[r][c]!=1: continue
  ext1.add(p)
  for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
   rr,cc=r+dr,c+dc
   if 0<=rr<R and 0<=cc<C and g[rr][cc]==1 and (rr,cc) not in ext1:q.append((rr,cc))
 out=[[8]*C for _ in range(R)]
 for r in range(R):
  for c in range(C):
   if g[r][c]==6:out[r][c]=6
   elif (r,c) in comp:
    is_boundary=(r==0 or c==0 or r==R-1 or c==C-1)
    halo=any((r+dr,c+dc) in ext1 for dr in [-1,0,1] for dc in [-1,0,1] if dr or dc)
    out[r][c]=7 if is_boundary or halo else 8
   elif g[r][c]==1 and any((r+dr,c+dc) in comp for dr in [-1,0,1] for dc in [-1,0,1] if dr or dc):
    out[r][c]=1
 return out,comp,ext1

def diff(got,truth):
 t=[list(map(int,x)) for x in truth.splitlines()]
 if len(got)!=len(t) or any(len(a)!=len(b) for a,b in zip(got,t)):return 'dim'
 return [(r,c,got[r][c],t[r][c]) for r in range(len(t)) for c in range(len(t[0])) if got[r][c]!=t[r][c]]
