def transform_rule2(s):
 g=[list(map(int,line)) for line in s.splitlines()]; R=len(g); C=len(g[0]);
 dirs4=[(1,0),(-1,0),(0,1),(0,-1)]; dirs8=[(dr,dc) for dr in [-1,0,1] for dc in [-1,0,1] if dr or dc]
 seeds=[(r,c) for r in range(R) for c in range(C) if g[r][c]==6]
 q=deque()
 for r,c in seeds:
  for dr,dc in dirs4:
   rr,cc=r+dr,c+dc
   if 0<=rr<R and 0<=cc<C and g[rr][cc]==8:q.append((rr,cc))
 comp=set()
 while q:
  r,c=q.popleft()
  if (r,c) in comp or g[r][c]!=8:continue
  comp.add((r,c))
  for dr,dc in dirs4:
   rr,cc=r+dr,c+dc
   if 0<=rr<R and 0<=cc<C and g[rr][cc]==8 and (rr,cc) not in comp:q.append((rr,cc))
 # ext1 8-connected
 q=deque((r,c) for r in range(R) for c in range(C) if g[r][c]==1 and (r==0 or c==0 or r==R-1 or c==C-1))
 ext1=set()
 while q:
  r,c=q.popleft()
  if (r,c) in ext1 or g[r][c]!=1:continue
  ext1.add((r,c))
  for dr,dc in dirs8:
   rr,cc=r+dr,c+dc
   if 0<=rr<R and 0<=cc<C and g[rr][cc]==1 and (rr,cc) not in ext1:q.append((rr,cc))
 # preserve connected 1 components touching comp
 keep1=set()
 q=deque()
 for r in range(R):
  for c in range(C):
   if g[r][c]==1 and any((r+dr,c+dc) in comp for dr,dc in dirs8):q.append((r,c))
 while q:
  r,c=q.popleft()
  if (r,c) in keep1 or g[r][c]!=1:continue
  keep1.add((r,c))
  for dr,dc in dirs8:
   rr,cc=r+dr,c+dc
   if 0<=rr<R and 0<=cc<C and g[rr][cc]==1 and (rr,cc) not in keep1:q.append((rr,cc))
 out=[[8]*C for _ in range(R)]
 for r in range(R):
  for c in range(C):
   if g[r][c]==6:out[r][c]=6
   elif (r,c) in keep1:out[r][c]=1
   elif (r,c) in comp:
    is_boundary=(r==0 or c==0 or r==R-1 or c==C-1)
    halo=any((r+dr,c+dc) in ext1 for dr,dc in dirs8)
    out[r][c]=7 if is_boundary or halo else 8
 return out,comp,ext1,keep1
